   496→	public static int[] getDictionaryInfo(SourceDictionary<?> sourceDictionary) {
   497→		int[] ret = {0, 0};
   498→		if (sourceDictionary.getClass().isAssignableFrom(SetDictionary.class)) {
   499→			SetDictionary dictionary = (SetDictionary) sourceDictionary;
   500→			ret[0] = dictionary.set().size();
   501→		} else if (sourceDictionary.getClass().isAssignableFrom(MapDictionary.class)) {
   502→			MapDictionary dictionary = (MapDictionary) sourceDictionary;
   503→			ret[0] = dictionary.map().keySet().size();
   504→		} else if (sourceDictionary.getClass().isAssignableFrom(SynonymDictionary.class)) {
   505→			SynonymDictionary dictionary = (SynonymDictionary) sourceDictionary;
   506→			ret[0] = dictionary.map().keySet().size();
   507→			ret[1] = dictionary.getWordSet().size();
   508→		} else if (sourceDictionary.getClass().isAssignableFrom(SpaceDictionary.class)) {
   509→			SpaceDictionary dictionary = (SpaceDictionary) sourceDictionary;
   510→			ret[0] = dictionary.map().keySet().size();
   511→			ret[1] = dictionary.getWordSet().size();
   512→		} else if (sourceDictionary.getClass().isAssignableFrom(CustomDictionary.class)) {
   513→			CustomDictionary dictionary = (CustomDictionary) sourceDictionary;
   514→			ret[0] = dictionary.map().keySet().size();
   515→			ret[1] = dictionary.getWordSet().size();
   516→		} else if (sourceDictionary.getClass().isAssignableFrom(InvertMapDictionary.class)) {
   517→			InvertMapDictionary dictionary = (InvertMapDictionary) sourceDictionary;
