   691→				CustomDictionary dictionary = (CustomDictionary) sourceDictionary;
   692→				Set<CharSequence> words = new HashSet<>();
   693→				Map<CharSequence, Object[]> map = dictionary.map();
   694→				for (CharSequence word : map.keySet()) {
   695→					StringBuilder sb = new StringBuilder();
