   705→			} else if (sourceDictionary.getClass().isAssignableFrom(InvertMapDictionary.class)) {
   706→				InvertMapDictionary dictionary = (InvertMapDictionary) sourceDictionary;
   707→				Set<CharSequence> words = new HashSet<>();
   708→				Map<CharSequence, CharSequence[]> map = dictionary.map();
   709→				for (CharSequence word : map.keySet()) {
